@extends('layouts.app') @section('title','Detail Setoran') @section('content')<div class="row g-3"><div class="col-lg-7"><div class="card"><div class="card-body"><h5>{{ $deposit->code }}</h5><p>Nasabah: <b>{{ $deposit->customer->name }}</b><br>Tanggal: {{ $deposit->deposit_date->format('d/m/Y') }}<br>Status: <span class="badge bg-secondary">{{ $deposit->status }}</span></p><div class="table-responsive"><table class="table"><thead><tr><th>Sampah</th><th>Berat</th><th>Harga/kg</th><th>Subtotal</th></tr></thead><tbody>@foreach($deposit->details as $i)<tr><td>{{ $i->waste->name }}</td><td>{{ $i->weight_kg }} kg</td><td>Rp {{ number_format($i->price_per_kg,0,',','.') }}</td><td>Rp {{ number_format($i->subtotal,0,',','.') }}</td></tr>@endforeach</tbody><tfoot><tr><th>Total</th><th>{{ $deposit->total_weight }} kg</th><th></th><th>Rp {{ number_format($deposit->total_amount,0,',','.') }}</th></tr></tfoot></table></div></div></div></div><div class="col-lg-5">@if(in_array(auth()->user()->role,['admin','petugas']) && !in_array($deposit->status,['completed','cancelled']))<div class="card mb-3"><div class="card-body"><h6>Ubah Status</h6><form method="post" action="{{ route('deposits.status',$deposit) }}">@csrf @method('patch')<select name="status" class="form-select mb-2">@if($deposit->status==='pending')<option value="weighed">weighed</option><option value="cancelled">cancelled</option>@elseif($deposit->status==='weighed')<option value="completed">completed</option><option value="cancelled">cancelled</option>@endif</select><textarea class="form-control mb-2" name="notes" placeholder="Catatan"></textarea><button class="btn btn-success">Proses</button></form></div></div>@endif<div class="card"><div class="card-body"><h6>Riwayat Status</h6>@foreach($deposit->histories as $h)<div class="border-start ps-2 mb-2"><b>{{ $h->from_status ?? '-' }} → {{ $h->to_status }}</b><br><small>{{ $h->created_at->format('d/m/Y H:i') }} · {{ $h->changer->name }}</small></div>@endforeach</div></div></d